nextflow_process {

    name "Test Process HLALA_PREPAREGRAPH"
    script "../main.nf"
    process "HLALA_PREPAREGRAPH"

    tag "modules"
    tag "modules_nfcore"
    tag "hlala"
    tag "hlala/preparegraph"

    test("homo_sapiens - prg") {
        config "./nextflow.config"

        def prg
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            prg = extract(modules_testdata_base_path + 'genomics/homo_sapiens/genome/PRG_test.zip').resolve('PRG_test')
        }
        when {
            process {
                """
                input[0] = [ [ id:'test'], file('${prg}') ]
                """
            }
        }

        then {
            def stable_name    = getAllFilesFromDir(outputDir, relative:true, includeDir: true)
            def stable_content = getAllFilesFromDir(outputDir, ignore: ['**/referenceGenome.fa.{bwt,pac,sa}','**/referenceGenome.fa_bowtie2idx*'])
            assertAll(
                { assert process.success },
                { assert snapshot(
                    stable_name,
                    stable_content,
                    process.out.findAll { key, val -> key.startsWith("versions") }
                ).match() }
            )
        }

    }

    test("homo_sapiens - prg - stub") {
        options "-stub"

        when {
            process {
                """
                input[0] = [ [ id:'test'], file('${moduleTestDir}') ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out, unstableKeys: ["graph"])).match() }
            )
        }

    }

}

params {
    outdir = "output/"
}

process {

    publishDir = [
        path: { "${params.outdir}/${task.process.tokenize(':')[-1].tokenize('_')[0].toLowerCase()}" },
        mode: 'copy'
    ]
}
